let metrics = [];
const status = document.querySelector('#status');
const filter = document.querySelector('#filter');
const refresh = document.querySelector('#refresh');
function render() {
  const visible = metrics.filter(item => item.title.toLowerCase().includes(filter.value.toLowerCase()));
  const section = document.querySelector('#metrics');
  section.replaceChildren();
  for (const item of visible) {
    const article = document.createElement('article');
    const title = document.createElement('h2'); title.textContent = item.title;
    const value = document.createElement('p'); value.className = 'value'; value.textContent = item.value;
    article.append(title, value); section.append(article);
  }
  status.textContent = visible.length ? `${visible.length} metrics shown.` : 'No matching metrics. Clear the filter to see all metrics.';
}
async function load() {
  refresh.disabled = true; status.textContent = 'Loading…';
  try {
    const response = await fetch('/api/metrics');
    if (!response.ok) throw new Error('Unavailable');
    metrics = await response.json(); render();
  } catch {
    status.textContent = 'Unable to refresh metrics. ' +
      (metrics.length ? 'Showing last successful data. ' : '') +
      'Try Refresh data.';
  } finally { refresh.disabled = false; }
}
filter.addEventListener('input', render);
refresh.addEventListener('click', load);
load();

:root { color-scheme: light; --ink: #182c2b; --muted: #465b58; --paper: #f3f5f2; --panel: #fff; --accent: #176454; --line: #b6c5bd; }
* { box-sizing: border-box; }
body { margin: 0; overflow-x: hidden; background: var(--paper); color: var(--ink); font: 1rem/1.5 system-ui, sans-serif; }
.shell { width: 1100px; max-width: 100%; margin: 2rem auto; padding: 1.5rem; }
header { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 1rem; margin-bottom: 2rem; }
h1 { margin: .25rem 0; font-size: 2rem; }
h2 { font-size: 1rem; margin: 0; }
p { margin: .5rem 0; }
.eyebrow { color: var(--accent); font-size: .75rem; font-weight: 700; letter-spacing: .125rem; }
label { display: block; font-weight: 600; }
input { width: 100%; padding: .75rem; border: 1px solid var(--muted); border-radius: .25rem; font: inherit; color: var(--ink); background: var(--panel); }
button { padding: .75rem 1rem; min-height: 44px; border: 1px solid var(--accent); border-radius: .25rem; background: var(--accent); color: white; font: inherit; white-space: nowrap; cursor: pointer; }
button:disabled { cursor: wait; }
:focus-visible { outline: 3px solid var(--ink); outline-offset: 3px; }
#status { min-height: 1.5rem; margin: 1rem 0; }
#metrics { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }
article { background: var(--panel); border: 1px solid var(--line); border-radius: .5rem; padding: 1.25rem; }
.value { font-size: 1.75rem; font-weight: 600; margin: .75rem 0 0; }
footer { margin-top: 2rem; color: var(--muted); font-size: .875rem; }
@media (max-width: 767px) {
  #metrics { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 479px) {
  #metrics { grid-template-columns: 1fr; }
}
